+func (b *Batch) Commit() error {
+	defer b.unlock()
+	if b.db.closed {
+		return ErrDBClosed
+	}
+
+	if b.options.ReadOnly || len(b.pendingWrites) == 0 {
+		return nil
+	}
+
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	// check if committed or rollbacked
+	if b.committed {
+		return ErrBatchCommitted
+	}
+	if b.rollbacked {
+		return ErrBatchRollbacked
+	}
+
+	batchId := b.batchId.Generate()
+	now := time.Now().UnixNano()
+	// Filter out expired records before writing to WAL
+	validRecords := make([]*LogRecord, 0, len(b.pendingWrites))
+	validIndices := make([]int, 0, len(b.pendingWrites))
+	for i, record := range b.pendingWrites {
+		if !record.IsExpired(now) {
+			validRecords = append(validRecords, record)
+			validIndices = append(validIndices, i)
+		}
+	}
+
+	// write to wal buffer only for non-expired records
+	for _, record := range validRecords {
+		buf := bytebufferpool.Get()
+		b.buffers = append(b.buffers, buf)
+		record.BatchId = uint64(batchId)
+		encRecord := encodeLogRecord(record, b.db.encodeHeader, buf)
+		b.db.dataFiles.PendingWrites(encRecord)
+	}
+
+	// write a record to indicate the end of the batch
+	buf := bytebufferpool.Get()
+	b.buffers = append(b.buffers, buf)
+	endRecord := encodeLogRecord(&LogRecord{
+		Key:  batchId.Bytes(),
+		Type: LogRecordBatchFinished,
+	}, b.db.encodeHeader, buf)
+	b.db.dataFiles.PendingWrites(endRecord)
+
+	// write to wal file
+	chunkPositions, err := b.db.dataFiles.WriteAll()
+	if err != nil {
+		b.db.dataFiles.ClearPendingWrites()
+		return err
+	}
+	
+	// Check that we got the right number of chunk positions
+	// (valid records + 1 for the batch finish record)
+	if len(chunkPositions) != len(validRecords)+1 {
+		panic("chunk positions length is not equal to valid records length + 1")
+	}
+
+	// flush wal if necessary
+	if b.options.Sync && !b.db.options.Sync {
+		if err := b.db.dataFiles.Sync(); err != nil {
+			return err
+		}
+	}
+
+	// write to index
+	// First handle valid (non-expired) records
+	chunkPosIdx := 0
+	for _, idx := range validIndices {
+		record := b.pendingWrites[idx]
+		if record.Type == LogRecordDeleted {
+			b.db.index.Delete(record.Key)
+		} else {
+			b.db.index.Put(record.Key, chunkPositions[chunkPosIdx])
+		}
+		chunkPosIdx++
+	}
+	
+	// Then handle expired records (delete them from index)
+	for _, record := range b.pendingWrites {
+		if record.IsExpired(now) {
+			b.db.index.Delete(record.Key)
+		}
+	}
+
+	// send events to watcher
+	if b.db.options.WatchQueueSize > 0 {
+		for _, record := range b.pendingWrites {
+			if record.IsExpired(now) {
+				continue // Don't send events for expired records
+			}
+			e := &Event{Key: record.Key, Value: record.Value, BatchId: record.BatchId}
+			if record.Type == LogRecordDeleted {
