@@ -0,0 +1,43 @@
+package main
+
+import (
+	"os"
+	"time"
+	"github.com/rosedblabs/rosedb/v2"
+	"github.com/rosedblabs/rosedb/v2/utils"
+)
+
+func main() {
+	// Remove existing test directory
+	os.RemoveAll("/tmp/rosedb_expire_test")
+	
+	// Specify the options
+	options := rosedb.DefaultOptions
+	options.DirPath = "/tmp/rosedb_expire_test"
+
+	// Open a database
+	db, err := rosedb.Open(options)
+	if err != nil {
+		panic(err)
+	}
+	defer func() {
+		_ = db.Close()
+	}()
+
+	// Put a key with a short TTL
+	err = db.PutWithTTL([]byte("test_key"), []byte("test_value"), time.Millisecond*100)
+	if err != nil {
+		panic(err)
+	}
+
+	// Wait for the key to expire
+	time.Sleep(time.Millisecond * 200)
+
+	// Try to get the key - should return error
+	_, err = db.Get([]byte("test_key"))
+	if err != nil {
+		println("Key correctly expired:", err.Error())
+	} else {
+		println("Key should have expired but didn't")
+	}
+}
